-- =====================================================================================
-- Reformulação regulatória 2026-09-16 — FOCUS COLINA (focus-colina)
-- Fragmento PL/pgSQL idempotente, casando por SLUG (nunca UUID), no estilo de
-- supabase/migrations/20260920000000_composicoes_conforme_rotulo.sql.
-- Fonte: docs/conformidade/reformulacao/focus-colina.md e scratchpad/fase2/focus-colina.json.
-- Sem guarda de contagem aqui (a consolidação põe); só o bloco deste produto.
-- NÃO APLICADO em nenhum banco. Veredito esperado: CONFORME CONDICIONADO A (laudo de origem Camellia sinensis da L-teanina nova; laudo de óxido de magnésio) — com a decisão do dono sobre a dose de colina (130 mg em 2 cápsulas)
-- =====================================================================================

-- 1. exclusão lógica das composições ativas atuais desta fórmula
update public.formula_compositions fc
set active = false, deleted_at = now(), reason_deleted = 'reformulação regulatória 2026-09-16'
from public.formulas f
where f.id = fc.formula_id and f.deleted_at is null and f.slug = 'focus-colina'
  and fc.deleted_at is null
  and coalesce(fc.metadata->>'fonte', '') <> 'reformulacao_2026-09-16';

-- 2. inserção das composições reformuladas (ingredient_id resolvido por slug; só se ainda não houver linha desta fonte)
insert into public.formula_compositions (formula_id, ingredient_name, quantity, unit, sort_order, ingredient_id, metadata)
select f.id, v.ingredient_name, v.quantity, v.unit::public.composition_unit, v.sort_order, i.id, v.metadata::jsonb
from (values
    ('focus-colina', 0, 'Colina (bitartarato de colina)', 130.0, 'mg', 'colina', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Colina", "forma_insumo": "Bitartarato de colina/Hidrogênio tartarato de colina (CAS 87-67-2)", "massa_insumo_mg": 320.1182, "laudo_lote": "91442 (Analitic, fabricante CA26010402USPS)", "laudo_validade": "03/01/2029", "laudo_vencido": false, "teor_pct": 40.61, "teor_fonte": "laudo", "ativo_mg": 130.0, "unidade_ativo": "mg", "minimo": 82.5, "maximo": 3235.15, "pct_do_maximo": 4.02, "linha_anexo": "I·Bitartarato de colina/Hidrogênio tartarato de colina; III·Colina 82,5 mg; IV·3.235,15 mg", "status": "dose ajustada", "e_sal": false, "observacao": "470 mg de colina exigem 1.157,35 mg de bitartarato — mais que a porção inteira (memorial rev02: 1.818,30 mg de insumos, 181,8% da porção). Em 2 cápsulas cabem 130 mg de colina (158% do mínimo; 4,0% do teto; 24% do VD). Alternativas com 3 ou 4 cápsulas na seção 8."}'),
    ('focus-colina', 1, 'L-tirosina', 290, 'mg', 'l-tirosina', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Tirosina", "forma_insumo": "L-Tirosina (CAS 60-18-4)", "massa_insumo_mg": 290.2903, "laudo_lote": "91382 (Analitic, fabricante 20250508)", "laudo_validade": "07/05/2028", "laudo_vencido": false, "teor_pct": 99.9, "teor_fonte": "laudo", "ativo_mg": 290, "unidade_ativo": "mg", "minimo": 262.5, "maximo": 2750, "pct_do_maximo": 10.55, "linha_anexo": "I·L-Tirosina; III·Tirosina 262,5 (nota viii: fenilalanina + tirosina ≥ 262,5 mg); IV·2.750 mg", "status": "dose ajustada", "e_sal": false, "observacao": "220 mg estavam abaixo do mínimo de 262,5 mg (nota viii; não há fenilalanina na fórmula). Nova dose 290 mg = 110% do mínimo, 10,5% do teto. (A fórmula em pó solúvel da própria fábrica já usa 262,76 mg.)"}'),
    ('focus-colina', 2, 'L-teanina de folhas de Camellia sinensis', 115, 'mg', 'l-teanina', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Teanina", "forma_insumo": "L-teanina de folhas de Camellia sinensis — insumo a adquirir (rota B)", "massa_insumo_mg": 115.0, "laudo_lote": "AUTO039250 (Lepuge, fabricante 202408145) — SÍNTESE QUÍMICA, não serve", "laudo_validade": "13/08/2027", "laudo_vencido": false, "teor_pct": 100.0, "teor_fonte": "assumido", "ativo_mg": 115, "unidade_ativo": "mg", "minimo": 50, "maximo": 250, "pct_do_maximo": 46.0, "linha_anexo": "I·L-teanina de folhas de Camellia sinensis (IN 318/2024); III/IV·Teanina", "status": "forma trocada (origem) — PENDENTE laudo", "e_sal": false, "observacao": "dose do rótulo (46% do teto) mantida; a origem tem de ser a de folhas de Camellia sinensis (única do Anexo I). Rota A (retirar) na seção 8 — para um produto de ''foco'', a teanina é parte do conceito."}'),
    ('focus-colina', 3, 'L-carnitina', 95, 'mg', 'l-carnitina', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "L-Carnitina", "forma_insumo": "Levocarnitina/L-carnitina (CAS 541-15-1)", "massa_insumo_mg": 95.5638, "laudo_lote": "26H14-B025-226329 (SM Empreendimentos, fabricante A2605097)", "laudo_validade": "20/05/2028", "laudo_vencido": false, "teor_pct": 99.41, "teor_fonte": "laudo", "ativo_mg": 95, "unidade_ativo": "mg", "minimo": null, "maximo": 2000, "pct_do_maximo": 4.75, "linha_anexo": "I·Levocarnitina/L-carnitina; III·NE; IV·2.000 mg", "status": "mantido", "e_sal": false, "observacao": "dose do rótulo (4,8% do teto). Lote de referência harmonizado na fase 3 (antes 216523, 95,95 %, 99,01 mg)."}'),
    ('focus-colina', 4, 'Magnésio (óxido de magnésio)', 70, 'mg', 'magnesio', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Magnésio", "forma_insumo": "Óxido de magnésio (MgO, CAS 1309-48-4) — insumo a adquirir", "massa_insumo_mg": 116.0782, "laudo_lote": null, "laudo_validade": null, "laudo_vencido": null, "teor_pct": 60.3, "teor_fonte": "assumido", "ativo_mg": 70, "unidade_ativo": "mg", "minimo": 63, "maximo": 350, "pct_do_maximo": 20.0, "linha_anexo": "I·Óxido de magnésio; III/IV·Magnésio", "status": "forma trocada + dose ajustada", "e_sal": false, "observacao": "60 mg estavam abaixo do mínimo de 63 mg; 70 mg = 111% do mínimo (20% do teto). O bisglicinato (laudo 90844 vencido) pesaria 231,6 mg para 70 mg e roubaria 115 mg da colina; o óxido pesa 116,08 mg. Mesmo insumo novo do Multivitamínico e do Nuviart."}'),
    ('focus-colina', 5, 'Inositol (mio-inositol)', 25, 'mg', 'inositol', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Inositol", "forma_insumo": "Inositol (Mio-inositol/Meso-inositol) (CAS 87-89-8)", "massa_insumo_mg": 25.035, "laudo_lote": "950479 (memorial rev02; digitalização, não relida). Alternativa em texto: IDNLABS YW20241103, 99,61%, val. 11/2028", "laudo_validade": "não relida", "laudo_vencido": null, "teor_pct": 99.86, "teor_fonte": "memorial", "ativo_mg": 25, "unidade_ativo": "mg", "minimo": null, "maximo": 2000, "pct_do_maximo": 1.25, "linha_anexo": "I·Inositol (Mio-inositol/Meso-inositol) (IN 76/2020); III·NE; IV·2 g", "status": "mantido", "e_sal": false, "observacao": "dose do rótulo (1,3% do teto)."}'),
    ('focus-colina', 6, 'Vitamina D3 (colecalciferol)', 5, 'mcg', 'vitamina-d', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Vitamina D", "forma_insumo": "Vitamina D3 (colecalciferol), pó 100.000 UI/g (CAS 67-97-0)", "massa_insumo_mg": 1.7391, "laudo_lote": "91408 (Analitic, fabricante 2025111601)", "laudo_validade": "15/11/2028", "laudo_vencido": false, "teor_pct": null, "teor_fonte": "laudo", "ativo_mg": 0.005, "unidade_ativo": "µg", "minimo": 3, "maximo": 50.0, "pct_do_maximo": 10.0, "linha_anexo": "I·Vitamina D3 (Colecalciferol); III/IV·Vitamina D", "status": "mantido", "e_sal": false, "observacao": "dose do rótulo (10,0% do teto; 33% do VD)."}'),
    ('focus-colina', 7, 'Vitamina B6 (cloridrato de piridoxina)', 1.3, 'mg', 'vitamina-b6', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Vitamina B6", "forma_insumo": "Cloridrato de piridoxina (CAS 58-56-0)", "massa_insumo_mg": 1.5817, "laudo_lote": "91188 (Analitic, fabricante 241229T092)", "laudo_validade": "28/12/2027", "laudo_vencido": false, "teor_pct": 99.9, "teor_fonte": "laudo", "ativo_mg": 1.3, "unidade_ativo": "mg", "minimo": 0.26, "maximo": 98.6, "pct_do_maximo": 1.32, "linha_anexo": "I·Cloridrato de piridoxina; III/IV·Vitamina B6", "status": "mantido", "e_sal": false, "observacao": "dose do rótulo (1,3% do teto)."}'),
    ('focus-colina', 8, 'Vitamina B12 (metilcobalamina)', 2.4, 'mcg', 'vitamina-b12', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Vitamina B12", "forma_insumo": "Metilcobalamina (CAS 13422-55-4)", "massa_insumo_mg": 0.0027, "laudo_lote": "219376 (26B20-B032-219376, Fagron/SM, fabricante 032511057)", "laudo_validade": "14/11/2030", "laudo_vencido": false, "teor_pct": 89.27, "teor_fonte": "laudo", "ativo_mg": 0.0024, "unidade_ativo": "µg", "minimo": 0.36, "maximo": 9.94, "pct_do_maximo": 24.14, "linha_anexo": "I·Metilcobalamina; III/IV·Vitamina B12", "status": "mantido (nome corrigido)", "e_sal": false, "observacao": "dose do rótulo (24,1% do teto; 100% do VD). O rótulo imprime ''cianocobalamina'', mas o lote adotado no memorial é metilcobalamina; o §6.1 do memorial usou 94,54% (teor de outro lote) — massa recalculada com 89,27%, como a fórmula solúvel da fábrica já faz (0,0027 mg)."}'),
    ('focus-colina', 9, 'Dióxido de silício (INS 551)', 31.145, 'mg', 'dioxido-de-silicio', '{"fonte": "reformulacao_2026-09-16", "excipiente": true, "ins": "551", "observacao": "q.s.p. 1.000 mg — quantum satis (IN 211/2023, 14.2). O rótulo vigente declara também ''agente de massa celulose microcristalina'', sem massa possível na fórmula atual (181,8%); com esta reformulação o agente de massa não é necessário."}')
) as v(slug, sort_order, ingredient_name, quantity, unit, ingredient_slug, metadata)
join public.formulas f on f.slug = v.slug and f.deleted_at is null
join public.ingredients i on i.slug = v.ingredient_slug and i.deleted_at is null
where not exists (
    select 1 from public.formula_compositions x
    where x.formula_id = f.id and x.deleted_at is null and x.metadata->>'fonte' = 'reformulacao_2026-09-16'
);

